{"cards": [{"node_code": "N_336d23bd5c5b053d", "definition": "甲状腺疾病的外科治疗是处理颈部甲状腺及甲状旁腺病变的手术分支，涵盖结节、癌肿、甲亢及功能异常的诊断、切除、重建及围术期管理。", "boundary": "本节点聚焦于甲状腺及甲状旁腺的外科干预，包括甲状腺癌根治、良性结节切除、甲亢手术及甲状旁腺疾病处理。不涵盖以放射性碘或药物为主的纯内科治疗，也不涵盖颈部其他非甲状腺/甲状旁腺结构（如淋巴结转移灶的独立清扫若未涉及甲状腺原发灶）的手术。", "includes": ["甲状腺癌、结节及甲亢的外科手术与术后管理", "甲状旁腺功能亢进或腺瘤的外科治疗", "甲状腺手术并发症（如喉返神经损伤）的预防与处理"], "excludes": ["甲状腺疾病的纯内分泌药物治疗", "颈部非甲状腺来源的肿瘤或淋巴结疾病手术"], "sibling_distinctions": [{"other_code": "N_38ef99e955a5de40", "rule": "甲状腺疾病的外科治疗处理颈部甲状腺及甲状旁腺，乳腺疾病的外科治疗处理胸部乳腺组织；两者解剖部位及器官系统完全不同。"}, {"other_code": "N_eb6c9da4a8aa5f33", "rule": "甲状腺疾病的外科治疗处理颈部腺体，疝与腹壁疾病处理腹壁完整性缺损；两者解剖部位及病理机制无重叠。"}], "cross_boundary_rule": "涉及甲状腺癌颈部淋巴结清扫时，若为甲状腺癌直接相关归本节点；若为其他头颈部肿瘤转移至颈部淋巴结，归相应头颈外科或肿瘤科。"}, {"node_code": "N_38ef99e955a5de40", "definition": "乳腺疾病的外科治疗是处理乳腺良恶性肿瘤、炎症及畸形的手术分支，涵盖乳腺癌根治、保乳手术、良性肿瘤切除及乳房重建。", "boundary": "本节点聚焦于乳腺组织的外科干预，包括乳腺癌手术、腋窝淋巴结清扫、乳腺良性病变切除及术后重建。不涵盖以化疗、放疗或内分泌治疗为主的纯内科/肿瘤科治疗，也不涵盖男性乳腺发育的纯药物治疗。", "includes": ["乳腺癌、乳腺增生及良性肿瘤的外科手术与重建", "腋窝淋巴结清扫及前哨淋巴结活检", "乳腺手术并发症（如乳糜漏、感染）的预防与处理"], "excludes": ["乳腺疾病的纯药物治疗或放射治疗", "胸部其他非乳腺来源的肿瘤或病变手术"], "sibling_distinctions": [{"other_code": "N_336d23bd5c5b053d", "rule": "乳腺疾病的外科治疗处理胸部乳腺组织，甲状腺疾病的外科治疗处理颈部甲状腺及甲状旁腺；两者解剖部位及器官系统完全不同。"}, {"other_code": "N_eb6c9da4a8aa5f33", "rule": "乳腺疾病的外科治疗处理胸部乳腺，疝与腹壁疾病处理腹壁完整性缺损；两者解剖部位及病理机制无重叠。"}], "cross_boundary_rule": "涉及乳腺癌胸壁侵犯时，若需切除部分胸壁归本节点（乳腺外科）；若胸壁病变独立于乳腺，归胸外科或骨肿瘤科。"}, {"node_code": "N_eb6c9da4a8aa5f33", "definition": "疝与腹壁疾病是处理腹壁完整性缺损及腹壁肿瘤的手术分支，涵盖腹股沟疝、切口疝、脐疝等诊断、修补及腹壁重建。", "boundary": "本节点聚焦于腹壁结构（肌肉、筋膜、皮肤）的缺损或病变，包括各类疝的修补、腹壁肿瘤切除及腹壁重建。不涵盖腹腔内脏器（如胃肠、肝胆）的原发性疾病手术，也不涵盖腹壁病变由腹腔内脏器直接侵犯引起的情况。", "includes": ["腹股沟疝、切口疝、脐疝等腹壁缺损的诊断与修补术", "腹壁肿瘤、脂肪瘤及瘢痕疙瘩的外科治疗", "腹壁重建及并发症（如复发、感染）的处理"], "excludes": ["腹腔内脏器（如胃肠、肝胆）的原发性疾病手术", "由腹腔内脏器直接侵犯腹壁引起的病变手术"], "sibling_distinctions": [{"other_code": "N_336d23bd5c5b053d", "rule": "疝与腹壁疾病处理腹壁完整性缺损，甲状腺疾病的外科治疗处理颈部腺体；两者解剖部位及病理机制无重叠。"}, {"other_code": "N_38ef99e955a5de40", "rule": "疝与腹壁疾病处理腹壁结构，乳腺疾病的外科治疗处理胸部乳腺组织；两者解剖部位及器官系统完全不同。"}], "cross_boundary_rule": "涉及腹壁肿瘤时，若肿瘤位于腹壁肌肉或筋膜层归本节点；若肿瘤起源于腹腔内脏器并侵犯腹壁，归相应脏器外科（如胃肠外科）。"}]}
